// Des: Flow queue in SQLite: flows, items with states and approvals, failed-chat marks
// Flo: new flow > add items with risk > approve > next pending item > set state > resume after restart
// I/O: Stor + ids and text (caller) > rows; item states todo doing wait done skip unsure fail
// ===================================================================
const std = @import("std"); const data = @import("st-stat-data.zig");
pub const Item = struct { id: i64, seq: i64, job: []const u8, args: []const u8, risk: []const u8, appr: bool, state: []const u8, note: []const u8, tries: i64 };
pub const Flow = struct { id: i64, name: []const u8, state: []const u8, ts: i64 };
pub fn flowNew(sto: *data.Stor, uuid: []const u8, name: []const u8, now_ms: i64) !i64 { var stm = try sto.dbzz.prep("INSERT INTO flow(uuid,name,ts,state) VALUES(?,?,?,'plan');"); defer stm.fini(); try stm.bindText(1, uuid); try stm.bindText(2, name); try stm.bindInt(3, now_ms); _ = try stm.step(); return sto.dbzz.lastRow(); }
pub fn flowSet(sto: *data.Stor, idz: i64, state: []const u8) !void { var stm = try sto.dbzz.prep("UPDATE flow SET state=? WHERE id=?;"); defer stm.fini(); try stm.bindText(1, state); try stm.bindInt(2, idz); _ = try stm.step(); if (sto.dbzz.changes() == 0) return error.Fail; }
pub fn flowLatest(sto: *data.Stor, aren: std.mem.Allocator) !?Flow { var stm = try sto.dbzz.prep("SELECT id,name,state,ts FROM flow ORDER BY id DESC LIMIT 1;"); defer stm.fini(); if (!try stm.step()) return null; return .{ .id = stm.colInt(0), .name = try aren.dupe(u8, stm.colText(1)), .state = try aren.dupe(u8, stm.colText(2)), .ts = stm.colInt(3) }; }
pub fn itemAdd(sto: *data.Stor, flow: i64, seq: i64, job: []const u8, args: []const u8, risk: []const u8, now_ms: i64) !i64 { var stm = try sto.dbzz.prep("INSERT INTO item(flow,seq,job,args,risk,appr,state,ts) VALUES(?,?,?,?,?,?,'todo',?);"); defer stm.fini(); try stm.bindInt(1, flow); try stm.bindInt(2, seq); try stm.bindText(3, job); try stm.bindText(4, args); try stm.bindText(5, risk); try stm.bindInt(6, if (std.mem.eql(u8, risk, "low")) 1 else 0); try stm.bindInt(7, now_ms); _ = try stm.step(); return sto.dbzz.lastRow(); }
fn rowOf(stm: *@import("st-stor-sqli.zig").Stmt, aren: std.mem.Allocator) !Item { return .{ .id = stm.colInt(0), .seq = stm.colInt(1), .job = try aren.dupe(u8, stm.colText(2)), .args = try aren.dupe(u8, stm.colText(3)), .risk = try aren.dupe(u8, stm.colText(4)), .appr = stm.colInt(5) != 0, .state = try aren.dupe(u8, stm.colText(6)), .note = try aren.dupe(u8, stm.colText(7)), .tries = stm.colInt(8) }; }
const COLS = "id,seq,job,args,risk,appr,state,note,tries";
pub fn itemsOf(sto: *data.Stor, aren: std.mem.Allocator, flow: i64) ![]Item { var stm = try sto.dbzz.prep("SELECT " ++ COLS ++ " FROM item WHERE flow=? ORDER BY seq;"); defer stm.fini(); try stm.bindInt(1, flow); var out: std.ArrayList(Item) = .empty; while (try stm.step()) try out.append(aren, try rowOf(&stm, aren)); return out.items; }
pub fn itemNext(sto: *data.Stor, aren: std.mem.Allocator, flow: i64) !?Item { var stm = try sto.dbzz.prep("SELECT " ++ COLS ++ " FROM item WHERE flow=? AND state IN ('todo','doing','wait') ORDER BY seq LIMIT 1;"); defer stm.fini(); try stm.bindInt(1, flow); if (!try stm.step()) return null; return try rowOf(&stm, aren); }
pub fn itemSet(sto: *data.Stor, idz: i64, state: []const u8, note: []const u8) !void { var stm = try sto.dbzz.prep("UPDATE item SET state=?, note=? WHERE id=?;"); defer stm.fini(); try stm.bindText(1, state); try stm.bindText(2, note); try stm.bindInt(3, idz); _ = try stm.step(); if (sto.dbzz.changes() == 0) return error.Fail; }
pub fn itemTry(sto: *data.Stor, idz: i64) !void { var stm = try sto.dbzz.prep("UPDATE item SET tries=tries+1 WHERE id=?;"); defer stm.fini(); try stm.bindInt(1, idz); _ = try stm.step(); }
pub fn itemApprove(sto: *data.Stor, idz: i64) !bool { var stm = try sto.dbzz.prep("UPDATE item SET appr=1 WHERE id=? AND appr=0 AND state IN ('todo','skip');"); defer stm.fini(); try stm.bindInt(1, idz); _ = try stm.step(); const chg = sto.dbzz.changes() > 0; if (chg) { var rs = try sto.dbzz.prep("UPDATE item SET state='todo', note='' WHERE id=? AND state='skip';"); defer rs.fini(); try rs.bindInt(1, idz); _ = try rs.step(); } return chg; }
pub fn approveAll(sto: *data.Stor, flow: i64) !u32 { var stm = try sto.dbzz.prep("SELECT id FROM item WHERE flow=? AND appr=0;"); defer stm.fini(); try stm.bindInt(1, flow); var ids: [256]i64 = undefined; var cnt: usize = 0; while (try stm.step()) { if (cnt < ids.len) { ids[cnt] = stm.colInt(0); cnt += 1; } } var done: u32 = 0; for (ids[0..cnt]) |idz| { if (try itemApprove(sto, idz)) done += 1; } return done; }
pub fn chatFailMark(sto: *data.Stor, chat: []const u8, now_ms: i64) !void { var stm = try sto.dbzz.prep("INSERT OR REPLACE INTO chatf(chat,ts) VALUES(?,?);"); defer stm.fini(); try stm.bindText(1, chat); try stm.bindInt(2, now_ms); _ = try stm.step(); }
pub fn chatFailedSince(sto: *data.Stor, chat: []const u8, since: i64) !bool { var stm = try sto.dbzz.prep("SELECT 1 FROM chatf WHERE chat=? AND ts>?;"); defer stm.fini(); try stm.bindText(1, chat); try stm.bindInt(2, since); return try stm.step(); }
pub fn metaInt(sto: *data.Stor, aren: std.mem.Allocator, key: []const u8, dflt: i64) !i64 { const txt = try sto.metaGet(aren, key) orelse return dflt; return std.fmt.parseInt(i64, txt, 10) catch dflt; }
pub fn metaPutInt(sto: *data.Stor, key: []const u8, valu: i64) !void { var buf: [24]u8 = undefined; try sto.metaSet(key, try std.fmt.bufPrint(&buf, "{d}", .{valu})); }
